INSERT INTO `ai_grade_suggestions` VALUES (1,'2026-11-13 10:05:36.475434','[{\"criterionId\":1,\"points\":4,\"reason\":\"Accurately explains that if-else handles boolean expressions and ranges, while switch matches single integer/char values against constant cases.\"},{\"criterionId\":2,\"points\":3,\"reason\":\"Correctly mentions the need for break statements to prevent execution from falling through to subsequent cases.\"},{\"criterionId\":3,\"points\":3,\"reason\":\"Provides clear and appropriate use cases, preferring switch for menu choices and if-else for complex or range conditions.\"}]','gemini-3.5-flash-lite','Excellent job! Your explanation captures the key technical differences between if-else chains and switch statements, correctly identifies the fall-through behavior with switch, and provides clear, practical examples for when to use each control structure.','gemini','2026-11-13 10:06:01.499735','ACCEPTED',1824,3),(2,'2026-11-14 04:08:20.819089','[{\"criterionId\":4,\"points\":5,\"reason\":\"The student clearly explains line charts for continuous trends over time and bar charts for discrete category comparisons.\"},{\"criterionId\":5,\"points\":5,\"reason\":\"The student addresses executive clarity by mentioning clear axis labels and avoiding misleading visuals by starting the y-axis at zero.\"}]','gemini-3.5-flash-lite','Excellent response! You accurately distinguished between the use cases for line and bar charts and demonstrated a strong understanding of how to maintain executive clarity and avoid misleading visuals.','gemini','2026-11-14 04:08:28.487972','ACCEPTED',1841,3),(3,'2026-11-14 14:27:44.588967','[{\"criterionId\":4,\"points\":3,\"reason\":\"The student mentions time as a factor for line charts, but does not clearly explain bar charts for discrete category comparisons or connect the choice properly to quarterly sales.\"},{\"criterionId\":5,\"points\":0,\"reason\":\"The student failed to address executive clarity, readability, labeling, or avoiding misleading axes.\"}]','gemini-3.5-flash-lite','Your answer touches on the time factor for line charts, but it misses key details. To improve, clearly explain that bar charts compare discrete categories (like quarters compared side-by-side) while line charts show continuous trends over time. Also, remember to discuss how to present this clearly to executives by focusing on readability, proper labeling, and avoiding misleading axes.','gemini','2026-11-14 14:27:51.626224','ACCEPTED',1898,3);
