DROP TABLE IF EXISTS `resource_files`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resource_files` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `content_type` varchar(120) NOT NULL,
  `extracted_char_count` int NOT NULL,
  `extracted_text` longtext,
  `extraction_note` varchar(500) DEFAULT NULL,
  `extraction_status` enum('EMPTY','FAILED','READY') NOT NULL,
  `file_name` varchar(120) NOT NULL,
  `page_count` int DEFAULT NULL,
  `sha256` varchar(64) NOT NULL,
  `size_bytes` bigint NOT NULL,
  `storage_key` varchar(64) NOT NULL,
  `uploaded_at` datetime(6) NOT NULL,
  `resource_id` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_resource_files_storage_key` (`storage_key`),
  UNIQUE KEY `UKn14m8arbh040xhl8ed29fcytp` (`resource_id`),
  KEY `idx_resource_files_sha256` (`sha256`),
  CONSTRAINT `FKomj3vrlwpma7n8jk14ll2vyxp` FOREIGN KEY (`resource_id`) REFERENCES `resources` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

