CREATE TABLE `student_topic_mastery` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `mastery_percent` double NOT NULL,
  `status` enum('DEVELOPING','GAP','INSUFFICIENT_DATA','STRENGTH') NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `student_id` bigint NOT NULL,
  `topic_id` bigint NOT NULL,
  `previous_mastery_percent` double DEFAULT NULL,
  `class_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_class_topic_mastery` (`student_id`,`class_id`,`topic_id`),
  KEY `FK4b4fdbnfbdut7rgus1wy46yic` (`topic_id`),
  KEY `FK9rhd5c9kvkumq1urn7og6jk49` (`class_id`),
  CONSTRAINT `FK4b4fdbnfbdut7rgus1wy46yic` FOREIGN KEY (`topic_id`) REFERENCES `topics` (`id`),
  CONSTRAINT `FK7yvbj28pkw5hx8368d2ag9lko` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`),
  CONSTRAINT `FK9rhd5c9kvkumq1urn7og6jk49` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=464 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
